import Vue from 'vue'  
import VueRouter from 'vue-router' // 只需要导入 VueRouter  
  
// 导入组件  
import Personal from '@/components/Personal'  
import Login from '@/components/Login'  
import Register from '@/components/Register'  
import Headers from '@/components/icon/headers.vue'
import Find from '@/components/Find.vue'
// 将 VueRouter 添加到 Vue 的全局插件中  
Vue.use(VueRouter)  
  
// 导出 router 实例  
export default new VueRouter({  
  routes: [  
    {  
      path: '/personal',  
      name: 'Personal',  
      component: Personal  
    },  
    {  
      path: '/',  
      name: 'Login',  
      component: Login  
    },  
    {  
      path: '/register',  
      name: 'register',  
      component: Register  
    },
    {
      path:'/header',
      name:'header',
      component:Headers
    },
    {
      path:'/find',
      name:'find',
      component:Find
    }  
  ],  
  mode: "history" // 使用 HTML5 history 模式  
})